// ====== 防抖（Debounce） ======
// 场景：搜索框输入、窗口resize、表单验证
// 在事件触发n秒后才执行，如果n秒内再次触发则重新计时
function debounce(fn, delay = 300) {
  // 闭包保存定时器ID
  let timer = null;

  // 返回防抖后的函数
  return function(...args) {
    // 每次调用先清除之前的定时器
    if (timer) clearTimeout(timer);

    // 设置新的定时器，delay毫秒后执行
    timer = setTimeout(() => {
      // 使用apply确保this指向和参数传递正确
      fn.apply(this, args);
      timer = null; // 执行后清除引用
    }, delay);
  };
}

