// ====== 节流（Throttle） ======
// 场景：滚动事件、鼠标移动、游戏帧率控制
// 在固定时间间隔内只执行一次函数
function throttle(fn, interval = 300) {
  // 记录上次执行时间
  let lastTime = 0;

  return function(...args) {
    const now = Date.now();

    // 当前时间与上次执行时间差 >= interval时执行
    if (now - lastTime >= interval) {
      lastTime = now; // 更新上次执行时间
      fn.apply(this, args);
    }
  };
}

