function rafThrottle(fn) {
  let rafId = null;

  return function(...args) {
    // 如果已有待处理的帧则跳过
    if (rafId) return;

    rafId = requestAnimationFrame(() => {
      fn.apply(this, args);
      rafId = null; // 执行后清除
    });
  };
}

