// ====== 条件类型：extends的三元运算 ======
// 根据条件决定最终类型
// 语法：T extends U ? X : Y
type IsString<T> = T extends string ? '是字符串' : '不是字符串';

type A = IsString<string>; // '是字符串'
type B = IsString<number>; // '不是字符串'

// 实际应用：提取特定类型
type ExtractString<T> = T extends string ? T : never;

