// ====== 类装饰器 ======
// 接收类的构造函数，可以修改或替换类
function sealed(constructor: Function) {
  // 使用Object.seal防止添加新属性
  Object.seal(constructor);
  Object.seal(constructor.prototype);
  console.log(`${constructor.name} 已被密封`);
}

// 装饰器工厂：返回装饰器函数，支持传参
function version(version: string) {
  return function <T extends { new(...args: any[]): {} }>(constructor: T) {
    // 返回一个新类，继承原类并添加属性
    return class extends constructor {
      apiVersion = version; // 添加版本号属性
    };
  };
}

@sealed
@version('1.0.0')
class UserService {
  constructor(private name: string) {}

  getUser() {
    return this.name;
  }
}

// 通过装饰器添加的属性
const service = new UserService('张三') as any;
console.log(service.apiVersion); // 输出 '1.0.0'

// ====== 方法装饰器 ======
// 可以拦截、修改方法的行为
function log(target: any, propertyKey: string, descriptor: PropertyDescriptor) {
  // target: 类的原型对象
  // propertyKey: 方法名
  // descriptor: 属性描述符
  const originalMethod = descriptor.value; // 保存原方法

  descriptor.value = function (...args: any[]) {
    console.log(`调用 ${propertyKey}，参数:`, args);
    const result = originalMethod.apply(this, args); // 调用原方法
    console.log(`${propertyKey} 返回:`, result);
    return result;
  };

  return descriptor;
}

// 装饰器工厂：限制方法调用频率
function throttle(delay: number) {
  let lastCall = 0;
  return function (target: any, propertyKey: string, descriptor: PropertyDescriptor) {
    const original = descriptor.value;
    descriptor.value = function (...args: any[]) {
      const now = Date.now();
      if (now - lastCall >= delay) {
        lastCall = now;
        return original.apply(this, args);
      }
    };
  };
}

class Calculator {
  @log
  add(a: number, b: number): number {
    return a + b;
  }

  @throttle(1000)
  heavyOperation(): void {
    console.log('执行耗时操作...');
  }
}

const calc = new Calculator();
calc.add(5, 3); // 输出: 调用 add，参数: [5, 3]  →  add 返回: 8

// ====== 属性装饰器 ======
// 可以观察或修改属性
function defaultValue(value: any) {
  return function (target: any, propertyKey: string) {
    let val = value;
    Object.defineProperty(target, propertyKey, {
      get: () => val,
      set: (newVal) => { val = newVal; },
      enumerable: true,
      configurable: true
    });
  };
}

class Settings {
  @defaultValue('light')
  theme!: string;
}

const settings = new Settings();
console.log(settings.theme); // 输出 'light'（默认值）

