import { useState, useEffect } from 'react';

// ====== useEffect基础：每次渲染后执行 ======
function Timer() {
  const [seconds, setSeconds] = useState(0);

  useEffect(() => {
    // 副作用：设置定时器
    const interval = setInterval(() => {
      setSeconds(prev => prev + 1); // 每秒递增
    }, 1000);

    // 清理函数：组件卸载时清除定时器
    return () => {
      clearInterval(interval);
      console.log('定时器已清除');
    };
  }, []); // 空依赖数组：只在组件挂载时执行一次

  return <div>已运行 {seconds} 秒</div>;
}

// ====== 依赖数组的三种情况 ======
function DataFetcher({ userId }) {
  const [user, setUser] = useState(null);

  // 情况1：无依赖数组 → 每次渲染都执行
  // useEffect(() => {
  //   console.log('每次渲染都执行');
  // });

  // 情况2：空依赖数组 → 只在挂载时执行一次
  // useEffect(() => {
  //   console.log('只在挂载时执行');
  // }, []);

  // 情况3：有依赖 → 依赖变化时执行
  useEffect(() => {
    console.log('userId变化，重新获取数据');
    // 模拟API请求
    const fetchUser = async () => {
      const response = await fetch(`/api/users/${userId}`);
      const data = await response.json();
      setUser(data);
    };
    fetchUser();
  }, [userId]); // userId变化时重新执行

  return (
    <div>
      {user ? <p>{user.name}</p> : <p>加载中...</p>}
    </div>
  );
}

// ====== 清理函数的作用 ======
// 在effect重新执行前或组件卸载时运行
function SearchInput() {
  const [query, setQuery] = useState('');

  useEffect(() => {
    // 防抖：延迟发送请求
    const timer = setTimeout(() => {
      if (query) {
        console.log('搜索:', query);
      }
    }, 500);

    // 清理函数：在下一次effect执行前清除上一次的定时器
    return () => {
      clearTimeout(timer);
    };
  }, [query]); // query变化时重新执行

  return (
    <input
      value={query}
      onChange={(e) => setQuery(e.target.value)}
      placeholder="搜索..."
    />
  );
}

// ====== DOM操作在useEffect中进行 ======
function AutoFocus() {
  const inputRef = useRef(null);

  useEffect(() => {
    // DOM操作必须在useEffect中，因为此时DOM已经渲染
    inputRef.current?.focus(); // 自动聚焦
  }, []);

  return <input ref={inputRef} placeholder="自动聚焦" />;
}

