import { useReducer } from 'react';

// ====== Reducer函数 ======
// reducer接收当前状态和action，返回新状态
// 语法：(state, action) => newState
const initialState = { count: 0, step: 1 };

function counterReducer(state, action) {
  // 根据action.type决定如何更新状态
  switch (action.type) {
    case 'increment':
      // 返回新状态对象，不修改原状态
      return { ...state, count: state.count + state.step };
    case 'decrement':
      return { ...state, count: state.count - state.step };
    case 'reset':
      return initialState; // 重置为初始状态
    case 'setStep':
      // action.payload携带额外数据
      return { ...state, step: action.payload };
    default:
      // 未知action，返回原状态
      return state;
  }
}

// ====== 使用useReducer ======
function Counter() {
  // useReducer返回[state, dispatch]
  const [state, dispatch] = useReducer(counterReducer, initialState);

  return (
    <div>
      <h2>计数：{state.count}</h2>
      <p>步长：{state.step}</p>

      {/* dispatch发送action对象 */}
      <button onClick={() => dispatch({ type: 'increment' })}>
        +{state.step}
      </button>
      <button onClick={() => dispatch({ type: 'decrement' })}>
        -{state.step}
      </button>
      <button onClick={() => dispatch({ type: 'reset' })}>
        重置
      </button>

      {/* 带payload的action */}
      <select
        value={state.step}
        onChange={(e) =>
          dispatch({ type: 'setStep', payload: Number(e.target.value) })
        }
      >
        <option value={1}>步长 1</option>
        <option value={5}>步长 5</option>
        <option value={10}>步长 10</option>
      </select>
    </div>
  );
}

// ====== 复杂状态：TodoList ======
// useReducer适合管理复杂的状态逻辑
const todoReducer = (state, action) => {
  switch (action.type) {
    case 'add':
      return [
        ...state,
        {
          id: Date.now(),
          text: action.payload,
          completed: false
        }
      ];
    case 'toggle':
      return state.map(todo =>
        todo.id === action.payload
          ? { ...todo, completed: !todo.completed }
          : todo
      );
    case 'delete':
      return state.filter(todo => todo.id !== action.payload);
    case 'clearCompleted':
      return state.filter(todo => !todo.completed);
    default:
      return state;
  }
};

function TodoApp() {
  const [todos, dispatch] = useReducer(todoReducer, []);
  const [text, setText] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    if (text.trim()) {
      dispatch({ type: 'add', payload: text });
      setText('');
    }
  };

  return (
    <div>
      <form onSubmit={handleSubmit}>
        <input value={text} onChange={e => setText(e.target.value)} />
        <button type="submit">添加</button>
      </form>

      <ul>
        {todos.map(todo => (
          <li key={todo.id}>
            <span
              onClick={() => dispatch({ type: 'toggle', payload: todo.id })}
              style={{
                textDecoration: todo.completed ? 'line-through' : 'none',
                cursor: 'pointer'
              }}
            >
              {todo.text}
            </span>
            <button
              onClick={() => dispatch({ type: 'delete', payload: todo.id })}
            >
              删除
            </button>
          </li>
        ))}
      </ul>

      {todos.some(t => t.completed) && (
        <button onClick={() => dispatch({ type: 'clearCompleted' })}>
          清除已完成
        </button>
      )}
    </div>
  );
}

import { useRef, useState, useEffect } from 'react';

// ====== 1. 访问DOM元素 ======
function AutoFocusInput() {
  // 创建ref对象，初始值为null
  const inputRef = useRef(null);

  useEffect(() => {
    // 组件挂载后，inputRef.current指向真实的DOM元素
    inputRef.current?.focus(); // 自动聚焦
  }, []);

  const handleClick = () => {
    // 通过ref操作DOM
    inputRef.current?.select(); // 选中文本
  };

  return (
    <div>
      <input ref={inputRef} placeholder="自动聚焦" />
      <button onClick={handleClick}>选中文本</button>
    </div>
  );
}

// ====== 2. 存储不触发重渲染的值 ======
// 与useState不同，修改ref.current不会触发重渲染
function RenderCounter() {
  const [count, setCount] = useState(0);
  // 用ref记录渲染次数
  const renderCount = useRef(0);

  // 每次渲染时递增
  renderCount.current += 1;

  return (
    <div>
      <p>计数：{count}</p>
      <p>渲染次数：{renderCount.current}</p>
      <button onClick={() => setCount(prev => prev + 1)}>
        增加
      </button>
    </div>
  );
}

// ====== 3. 保存定时器ID ======
function Timer() {
  const [seconds, setSeconds] = useState(0);
  // 用ref保存定时器ID，不触发重渲染
  const intervalRef = useRef(null);

  const start = () => {
    if (intervalRef.current) return; // 防止重复启动
    intervalRef.current = setInterval(() => {
      setSeconds(prev => prev + 1);
    }, 1000);
  };

  const stop = () => {
    clearInterval(intervalRef.current);
    intervalRef.current = null;
  };

  const reset = () => {
    stop();
    setSeconds(0);
  };

  // 组件卸载时清理
  useEffect(() => {
    return () => clearInterval(intervalRef.current);
  }, []);

  return (
    <div>
      <p>{seconds} 秒</p>
      <button onClick={start}>开始</button>
      <button onClick={stop}>停止</button>
      <button onClick={reset}>重置</button>
    </div>
  );
}

// ====== 4. 获取上一个状态值 ======
function usePrevious(value) {
  const ref = useRef();
  useEffect(() => {
    ref.current = value; // 在渲染后更新ref
  }, [value]);
  return ref.current; // 返回的是上一次的值
}

function PreviousValueDemo() {
  const [count, setCount] = useState(0);
  const prevCount = usePrevious(count);

  return (
    <div>
      <p>当前：{count}，上一次：{prevCount ?? '无'}</p>
      <button onClick={() => setCount(prev => prev + 1)}>增加</button>
    </div>
  );
}

