// ====== Vue 3 响应式系统核心原理 ======
// 基于 Proxy 和 Reflect 的响应式系统

// 1. 依赖收集：track函数
// 存储依赖关系：targetMap → depsMap → dep(Set)
const targetMap = new WeakMap(); // 全局依赖映射表

let activeEffect = null; // 当前活跃的effect

// track：追踪依赖，将effect添加到依赖集合
function track(target, key) {
  if (!activeEffect) return; // 没有活跃effect则跳过

  // 获取或创建target的依赖映射
  let depsMap = targetMap.get(target);
  if (!depsMap) {
    targetMap.set(target, (depsMap = new Map()));
  }

  // 获取或创建key的依赖集合
  let dep = depsMap.get(key);
  if (!dep) {
    depsMap.set(key, (dep = new Set()));
  }

  // 将当前effect添加到依赖集合
  dep.add(activeEffect);
}

// 2. 触发更新：trigger函数
function trigger(target, key) {
  const depsMap = targetMap.get(target);
  if (!depsMap) return;

  const dep = depsMap.get(key);
  if (dep) {
    // 执行所有依赖该key的effect
    dep.forEach(effect => effect());
  }
}

// 3. reactive：使用Proxy创建响应式对象
function reactive(target) {
  // 只处理对象类型
  if (typeof target !== 'object' || target === null) {
    return target;
  }

  return new Proxy(target, {
    // get陷阱：读取属性时追踪依赖
    get(obj, key, receiver) {
      const result = Reflect.get(obj, key, receiver);
      // 追踪依赖：记录谁在使用这个属性
      track(obj, key);
      // 深层响应式：嵌套对象也转为reactive
      return typeof result === 'object' && result !== null
        ? reactive(result)
        : result;
    },

    // set陷阱：设置属性时触发更新
    set(obj, key, value, receiver) {
      const oldValue = obj[key];
      const result = Reflect.set(obj, key, value, receiver);
      // 值变化时触发更新
      if (oldValue !== value) {
        trigger(obj, key);
      }
      return result;
    },

    // deleteProperty陷阱：删除属性时触发更新
    deleteProperty(obj, key) {
      const hadKey = Object.prototype.hasOwnProperty.call(obj, key);
      const result = Reflect.deleteProperty(obj, key);
      if (hadKey) {
        trigger(obj, key);
      }
      return result;
    }
  });
}

// 4. ref：基本类型的响应式包装
function ref(value) {
  // 创建包含value属性的响应式对象
  const refObject = {
    get value() {
      // 读取时追踪依赖
      track(refObject, 'value');
      return value;
    },
    set value(newValue) {
      if (newValue !== value) {
        value = newValue;
        // 设置时触发更新
        trigger(refObject, 'value');
      }
    }
  };
  return refObject;
}

// 5. effect：创建副作用函数
function effect(fn) {
  // 包装函数，设置activeEffect
  const effectFn = () => {
    activeEffect = effectFn;
    fn(); // 执行副作用函数，触发track
    activeEffect = null;
  };
  effectFn(); // 立即执行一次
  return effectFn;
}

