package main

import "fmt"

func main() {
    // --- if 条件判断（支持初始化语句） ---
    score := 85

    if score >= 90 {  // if：条件不需要括号
        fmt.Println("等级: 优秀")
    } else if score >= 80 {  // else if：必须紧接上一个}之后
        fmt.Println("等级: 良好")
    } else if score >= 60 {
        fmt.Println("等级: 及格")
    } else {
        fmt.Println("等级: 不及格")
    }

    // if支持初始化语句（Go特色）
    if grade := getGrade(score); grade == "良好" {
        // ↑ grade := getGrade(score)：初始化语句，仅在if作用域内可见
        fmt.Println("恭喜获得良好等级！")
    }
    // fmt.Println(grade)  // 编译错误：grade在if外部不可见

    // --- switch 多分支选择 ---
    day := 3
    switch day {  // switch：默认不穿透（无需break）
    case 1:
        fmt.Println("周一：开始新的一周")
    case 2:
        fmt.Println("周二：继续加油")
    case 3:
        fmt.Println("周三：一周过半")
    case 6, 7:  // 多个值用逗号分隔
        fmt.Println("周末：好好休息")
    default:
        fmt.Println("工作日")
    }

    // switch 无表达式（替代if-else链）
    switch {  // 无表达式：每个case是一个条件
    case score >= 90:
        fmt.Println("switch方式: 优秀")
    case score >= 60:
        fmt.Println("switch方式: 及格")
    default:
        fmt.Println("switch方式: 不及格")
    }

    // switch 类型断言
    var x interface{} = "hello"
    switch v := x.(type) {  // .(type) 只能在switch中使用
    case int:
        fmt.Println("整数:", v)
    case string:
        fmt.Println("字符串:", v)
    default:
        fmt.Println("未知类型")
    }

    // --- for 循环（Go唯一的循环关键字） ---
    // 形式1：传统for循环
    fmt.Println("\n传统for循环:")
    for i := 1; i <= 5; i++ {  // for 初始化; 条件; 迭代
        fmt.Print(i, " ")
    }
    fmt.Println()

    // 形式2：while风格（条件循环）
    fmt.Println("while风格:")
    count := 0
    for count < 3 {  // 只有条件，类似while
        fmt.Print(count, " ")
        count++
    }
    fmt.Println()

    // 形式3：无限循环
    // for { ... }  // 等价于 while(true)

    // 形式4：range遍历
    fruits := []string{"苹果", "香蕉", "橘子"}
    fmt.Println("range遍历:")
    for i, fruit := range fruits {
        fmt.Printf("  [%d] %s\n", i, fruit)
    }

    // break 与 continue
    fmt.Println("break: 找到第一个偶数")
    numbers := []int{1, 3, 5, 6, 7, 9}
    for _, n := range numbers {
        if n%2 == 0 {
            fmt.Println("  找到:", n)
            break  // 终止循环
        }
    }
}

// ============================================
// 【初级】Go 函数定义与多返回值
// ============================================

package main

import (
    "errors"  // 错误处理
    "fmt"
)

// --- 基本函数定义 ---
func greet(name string) string {
    // ↑ func：函数声明关键字
    // ↑ (name string)：参数列表，参数名在前，类型在后
    // ↑ string：返回值类型
    return "你好，" + name + "！欢迎学习Go！"
}

// --- 多返回值（Go核心特性） ---
func divide(a, b float64) (float64, error) {
    // ↑ (float64, error)：返回两个值
    // ↑ 第二个返回值通常是error，用于错误处理
    if b == 0 {
        return 0, errors.New("除数不能为零")
        // ↑ errors.New()：创建错误信息
    }
    return a / b, nil  // nil：表示无错误
}

// --- 命名返回值 ---
func calculateStats(numbers []int) (sum int, avg float64) {
    // ↑ (sum int, avg float64)：命名返回值
    // ↑ 命名返回值自动初始化为零值，可直接使用
    for _, n := range numbers {
        sum += n  // sum已在返回值声明处定义
    }
    if len(numbers) > 0 {
        avg = float64(sum) / float64(len(numbers))
        // ↑ avg也是命名返回值
    }
    return  // 裸return：自动返回命名返回值
}

// --- 可变参数 ---
func sumAll(nums ...int) int {
    // ↑ ...int：可变参数，nums是[]int切片
    total := 0
    for _, n := range nums {
        total += n
    }
    return total
}

// --- 函数作为参数 ---
func applyOperation(a, b int, op func(int, int) int) int {
    // ↑ op func(int, int) int：函数类型参数
    return op(a, b)
}

func main() {
    // 调用基本函数
    fmt.Println(greet("小明"))

    // 调用多返回值函数
    result, err := divide(10, 3)
    // ↑ 接收两个返回值
    if err != nil {
        fmt.Println("错误:", err)
    } else {
        fmt.Printf("10 / 3 = %.2f\n", result)
    }

    // 忽略返回值（用_）
    result2, _ := divide(10, 2)
    // ↑ _：空白标识符，忽略不需要的返回值
    fmt.Println("10 / 2 =", result2)

    // 除零错误处理
    _, err = divide(10, 0)
    if err != nil {
        fmt.Println("除零错误:", err)
    }

    // 命名返回值
    sum, avg := calculateStats([]int{85, 92, 78, 95, 88})
    fmt.Printf("\n总和: %d, 平均: %.2f\n", sum, avg)

    // 可变参数
    fmt.Println("可变参数求和:", sumAll(1, 2, 3, 4, 5))

    // 函数作为参数
    multiply := func(a, b int) int { return a * b }
    // ↑ 匿名函数（闭包）
    fmt.Println("函数参数:", applyOperation(5, 3, multiply))

    // 匿名函数直接调用
    result3 := func(x, y int) int {
        return x + y
    }(10, 20)  // 定义后立即调用
    fmt.Println("匿名函数直接调用:", result3)
}

