// ============================================
// 【高级】Go 泛型编程（Go 1.18+）
// ============================================

package main

import (
    "fmt"
    "golang.org/x/exp/constraints"
    // ↑ constraints包：常用类型约束
)

// --- 泛型函数：类型参数 ---
func Min[T constraints.Ordered](a, b T) T {
    // ↑ [T constraints.Ordered]：类型参数列表
    // ↑ T：类型参数名
    // ↑ constraints.Ordered：类型约束（可比较的有序类型）
    if a < b {
        return a
    }
    return b
}

// --- 泛型函数：多类型参数 ---
func MapKeys[K comparable, V any](m map[K]V) []K {
    // ↑ [K comparable, V any]：两个类型参数
    // ↑ comparable：可比较的类型约束
    // ↑ any：任意类型（interface{}的别名）
    keys := make([]K, 0, len(m))
    for k := range m {
        keys = append(keys, k)
    }
    return keys
}

// --- 泛型结构体 ---
type Stack[T any] struct {
    // ↑ [T any]：类型参数化结构体
    items []T
}

// 泛型方法
func (s *Stack[T]) Push(item T) {
    // ↑ (s *Stack[T])：接收者包含类型参数
    s.items = append(s.items, item)
}

func (s *Stack[T]) Pop() (T, bool) {
    var zero T  // 类型参数的零值
    if len(s.items) == 0 {
        return zero, false
    }
    last := s.items[len(s.items)-1]
    s.items = s.items[:len(s.items)-1]
    return last, true
}

func (s *Stack[T]) Peek() (T, bool) {
    var zero T
    if len(s.items) == 0 {
        return zero, false
    }
    return s.items[len(s.items)-1], true
}

func (s *Stack[T]) Size() int {
    return len(s.items)
}

// --- 泛型接口 ---
type Set[T comparable] interface {
    // ↑ [T comparable]：泛型接口
    Add(item T)
    Contains(item T) bool
    Remove(item T)
}

// 泛型Set实现
type HashSet[T comparable] struct {
    data map[T]struct{}
    // ↑ struct{}：零内存占用的空结构体
}

func NewHashSet[T comparable]() *HashSet[T] {
    // ↑ 泛型构造函数
    return &HashSet[T]{
        data: make(map[T]struct{}),
    }
}

func (s *HashSet[T]) Add(item T) {
    s.data[item] = struct{}{}
}

func (s *HashSet[T]) Contains(item T) bool {
    _, exists := s.data[item]
    return exists
}

func (s *HashSet[T]) Remove(item T) {
    delete(s.data, item)
}

func (s *HashSet[T]) Size() int {
    return len(s.data)
}

// --- 自定义类型约束 ---
type Number interface {
    // ↑ 自定义约束接口
    ~int | ~int64 | ~float64
    // ↑ ~int：包括int和基于int的自定义类型
    // ↑ |：类型并集
}

func Sum[T Number](values []T) T {
    var total T
    for _, v := range values {
        total += v
    }
    return total
}

func main() {
    fmt.Println("=== Go 泛型编程（Go 1.18+） ===")

    // 泛型函数
    fmt.Println("Min(10, 20):", Min(10, 20))
    fmt.Println("Min(3.14, 2.71):", Min(3.14, 2.71))
    fmt.Println("Min('a', 'z'):", string(Min('a', 'z')))

    // MapKeys
    m := map[string]int{"a": 1, "b": 2, "c": 3}
    fmt.Println("\nMapKeys:", MapKeys(m))

    // 泛型Stack
    fmt.Println("\n=== 泛型Stack ===")
    intStack := Stack[int]{}
    intStack.Push(10)
    intStack.Push(20)
    intStack.Push(30)
    fmt.Printf("Stack大小: %d\n", intStack.Size())

    if val, ok := intStack.Pop(); ok {
        fmt.Println("Pop:", val)
    }
    if val, ok := intStack.Peek(); ok {
        fmt.Println("Peek:", val)
    }

    // 泛型HashSet
    fmt.Println("\n=== 泛型HashSet ===")
    set := NewHashSet[string]()
    set.Add("Go")
    set.Add("Java")
    set.Add("Python")
    set.Add("Go")  // 重复，不会添加
    fmt.Printf("Set大小: %d\n", set.Size())
    fmt.Println("包含Go?", set.Contains("Go"))
    fmt.Println("包含Rust?", set.Contains("Rust"))

    // 自定义约束
    fmt.Println("\nSum:", Sum([]int{1, 2, 3, 4, 5}))
    fmt.Println("Sum:", Sum([]float64{1.5, 2.5, 3.5}))

    // 泛型优势
    fmt.Println("\n=== 泛型 vs 反射 ===")
    fmt.Println("泛型: 编译期类型安全，性能好")
    fmt.Println("反射: 运行时类型检查，有性能开销")
    fmt.Println("建议: 优先使用泛型，反射用于框架开发")
}

